		#region Constructors

		public OrderEntryForm(WhsOrder order, INotificationSubscriberQueryUser whsNotificationSubscriberGuiHelper)
			: base(order)
		{
			WhsNotificationSubscriberGuiHelper = GUIFormHelper.ArgumentNotNullWithFormDispose(this, whsNotificationSubscriberGuiHelper, nameof(whsNotificationSubscriberGuiHelper));
			ZFormPostingButtonsStrategy.SetupPosting(this, PostingButtonsUserControl);

			AddPlugIns();
			AddMenuItems(order);

			CheckIfNeedValidationAndValidate(order);

			AddScreeningLogsTabPage();
		}

		void AddScreeningLogsTabPage()
		{
			if (!zEventTabPage1.IsDisposed)
			{
				var screeningLogControl = new StmEntityScreeningLogControl();
				screeningLogControl.SetBindingMember(nameof(WhsOrder.RelatedOrgPartyScreeningStatusCollection));
				zEventTabPage1.AddAdditionalTab(Res.GetString("0C0C8E91-C95A-43F6-8A15-10DED750FC02", "Denied Party Screening Logs"), screeningLogControl);
			}
		}

		protected override void OnLoad(EventArgs e)
		{
			base.OnLoad(e);

			using (Order.SuspendSettingHasChanges())
			{
				new DeniedPartyScreeningPresentationManager().ResynchronizeScreeningStatus(false, new[] { Order }, null);
			}
		}

		protected override void OnShown(EventArgs e)
		{
			this.OrderEntryUserControl.Focus();
			base.OnShown(e);
		}

		#region AddMenuItems

		void AddMenuItems(WhsOrder order)
		{
			ZFormMenuStrategy.AddActionsMenuItem(this, ResString.GetMultilingualString("7f53105e-e440-4c9d-a249-0eb51d69af3b", "Create all Work Orders by their Bills of Materials"), new EventHandler(OnCreateWorkOrders));
			ZFormMenuStrategy.AddActionsMenuItem(this, ResString.GetMultilingualString("abd4b75e-2702-4474-bf77-9cfd0e31b83f", "Override Fulfillment Rule"), OnOverrideFulfillmentRule);
			CancelReactivateMenuItem = ZFormMenuStrategy.AddActionsMenuItem(this, CancelReactivateOrderMenuItemText, OnCancelReactivateDocket);

			ZFormMenuStrategy.AddActionsMenuItem(this, "-", null);

			var exportJob = new ZMenuItem(ResString.GetMultilingualString("c232b537-8d58-4c90-8fa0-931cbc4e9e10", "Export Order Confirmation Job to XML"));
			ZFormMenuStrategy.AddInterfaceConnectorMenuItem(this, exportJob);

			var exportToEmail = new WhsOrderExportToEmailMenuItem(order, new WhsOrderConfirmationValueObjectDataAdapter());
			exportJob.MenuItems.Add(exportToEmail);

			var exportToFile = new WhsOrderExportToFileMenuItem(order, new WhsOrderConfirmationValueObjectDataAdapter());
			exportJob.MenuItems.Add(exportToFile);

			var exportJobIFS = new ZMenuItem(ResString.GetMultilingualString("e77b6f49-4657-4fc1-a3ec-7521cb9b2141", "Export Order to IFS"));
			ActionsMenuItem.MenuItems.Add(exportJobIFS);

			var exportToFileIFS = new WhsOrderExportToFileMenuItemIFS(order, new WhsOrderCartageValueObjectDataAdapterIFS());
			ZFormMenuStrategy.AddInterfaceConnectorMenuItem(exportJobIFS, exportToFileIFS);

			var exportToEmailIFS = new WhsOrderExportToEmailMenuItemIFS(order, new WhsOrderCartageValueObjectDataAdapterIFS());
			ZFormMenuStrategy.AddInterfaceConnectorMenuItem(exportJobIFS, exportToEmailIFS);

			WorkflowTabPage.Initialize(order);

			RelatedJobsMenuItem = this.CreateRelatedJobsMainMenuItem<OrderEntryForm, WhsOrder>();

			var deniedPartyScreeningPresentationManager = new DeniedPartyScreeningPresentationManager();
			deniedPartyScreeningPresentationManager.CreateMenusForJob(this);
			new DeniedPartyScreeningActionsProvider(this, order).AddJobsMenuItem();

			this.HookCartageClickEvent(RelatedJobsMenuItem);
		}

		ZMenuItem RelatedJobsMenuItem;

