		#region Release Button

		void ReleaseButton_Click(object sender, EventArgs e)
		{
			if (Order.IsAttachedToPickButNotFinalised || Order.IsFinalised)
			{
				ShowReleaseFormForExistingPick();
			}
			else
			{
				Globals.Message.ShowInformation(OrderMustBePickedErrorMsg, Res.GetString("406a40d4-df54-417c-bfe7-65e2322fb903", "Message"));
			}
		}

		void ShowReleaseFormForExistingPick()
		{
			if (Order.HasChanges)
			{
				Globals.Message.ShowWarning(Res.GetString("bad8d148-c678-48a0-8d57-7deeaf023d94", "Please save this Order before going to the Release Form"));
			}
			else
			{
				var pick = Order.Pick;
				if (pick != null)
				{
					var releaseEntryForm = (ReleaseEntryForm)ReleaseController.ShowEditForm(pick);
					releaseEntryForm?.SetInitialOrderToSelectInGrid(Order.PK);
				}
				else
				{
					Globals.Message.ShowWarning(Res.GetString("3492259b-923a-4a2c-8e27-111e25ec9d88", "Please create a Pick before going to the Release Form."));
				}
			}
		}

