		#region Cancel Docket Handler

		void OnCancelReactivateDocket(object sender, EventArgs e)
		{
			if (Env.Security.WhsOrderCancel.IsAllowed)
			{
				if (Order.CanCancel() != ZString.Empty)
				{
					Globals.Message.ShowError(Order.CanCancel());
				}
				else
				{
					Order.CancelReactivateDocket();

					CancelReactivateMenuItem.Text = CancelReactivateOrderMenuItemText;
				}
			}
			else
			{
				Env.Security.ShowError(Env.Security.WhsOrderCancel);
			}
		}

