		#region Saving

		protected override ContinueWithSave ShowPreSaveDialogs()
		{
			if (Order.ShouldPromptToSaveSupplierBuyerRelationship)
			{
				if (ShowConfirmationForNewSupplierBuyerRelationship() == DialogResult.Yes)
				{
					Order.AddNewBuyerSupplierLink();
				}
			}
			return base.ShowPreSaveDialogs();
		}

		protected override ContinueWithSave ValidateAndSave()
		{
			Order.IsSavedFromOrderForm = true; // simpler than piggy backing validation because we would need WhsOrderFormValidation class to piggy back.
			return base.ValidateAndSave();
		}

		protected override void HandleSaveException(Exception e)
		{
			if (!ZFormExceptionHandler.HandleSaveExceptionForTriggers(e))
			{
				base.HandleSaveException(e);
			}
		}

